import Database from "better-sqlite3";
import path from "path";

const DB_PATH = path.resolve(process.cwd(), "poll.db");

let db: Database.Database | null = null;

export function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH);
    // Enable WAL mode for better concurrent read/write performance
    db.pragma("journal_mode = WAL");
    // Enable busy timeout to wait for locks instead of immediately failing
    db.pragma("busy_timeout = 5000");
  }
  return db;
}

export interface Poll {
  id: string;
  question: string;
}

export interface Option {
  id: number;
  poll_id: string;
  text: string;
  votes: number;
}

export function getPoll(pollId: string): Poll | undefined {
  const database = getDb();
  const stmt = database.prepare("SELECT id, question FROM polls WHERE id = ?");
  return stmt.get(pollId) as Poll | undefined;
}

export function getOptions(pollId: string): Option[] {
  const database = getDb();
  const stmt = database.prepare(
    "SELECT id, poll_id, text, votes FROM options WHERE poll_id = ? ORDER BY id"
  );
  return stmt.all(pollId) as Option[];
}

export function getOptionById(optionId: number): Option | undefined {
  const database = getDb();
  const stmt = database.prepare(
    "SELECT id, poll_id, text, votes FROM options WHERE id = ?"
  );
  return stmt.get(optionId) as Option | undefined;
}

export function castVote(pollId: string, optionId: number): Option[] {
  const database = getDb();

  // Use a transaction for atomic vote increment
  const voteTransaction = database.transaction(() => {
    // Increment the vote count atomically
    const updateStmt = database.prepare(
      "UPDATE options SET votes = votes + 1 WHERE id = ? AND poll_id = ?"
    );
    const result = updateStmt.run(optionId, pollId);

    if (result.changes === 0) {
      throw new Error("Option not found for this poll");
    }

    // Return updated vote counts for all options of the poll
    const selectStmt = database.prepare(
      "SELECT id, poll_id, text, votes FROM options WHERE poll_id = ? ORDER BY id"
    );
    return selectStmt.all(pollId) as Option[];
  });

  return voteTransaction();
}

export function checkRateLimit(
  pollId: string,
  ip: string,
  windowSeconds: number = 5
): boolean {
  const database = getDb();
  const now = Math.floor(Date.now() / 1000);
  const cutoff = now - windowSeconds;

  const stmt = database.prepare(
    "SELECT id FROM votes_log WHERE poll_id = ? AND ip = ? AND timestamp > ? LIMIT 1"
  );
  const recentVote = stmt.get(pollId, ip, cutoff);

  return recentVote === undefined;
}

export function logVote(pollId: string, ip: string): void {
  const database = getDb();
  const now = Math.floor(Date.now() / 1000);
  const stmt = database.prepare(
    "INSERT INTO votes_log (poll_id, ip, timestamp) VALUES (?, ?, ?)"
  );
  stmt.run(pollId, ip, now);
}

export function castVoteWithRateLimit(
  pollId: string,
  optionId: number,
  ip: string
): Option[] {
  const database = getDb();

  // Use a transaction for atomicity: check rate limit, log vote, increment vote
  const voteTransaction = database.transaction(() => {
    const now = Math.floor(Date.now() / 1000);
    const cutoff = now - 5;

    // Check rate limit within the transaction for atomicity
    const rateStmt = database.prepare(
      "SELECT id FROM votes_log WHERE poll_id = ? AND ip = ? AND timestamp > ? LIMIT 1"
    );
    const recentVote = rateStmt.get(pollId, ip, cutoff);

    if (recentVote) {
      throw new Error("Rate limit exceeded");
    }

    // Log the vote
    const logStmt = database.prepare(
      "INSERT INTO votes_log (poll_id, ip, timestamp) VALUES (?, ?, ?)"
    );
    logStmt.run(pollId, ip, now);

    // Increment the vote count atomically
    const updateStmt = database.prepare(
      "UPDATE options SET votes = votes + 1 WHERE id = ? AND poll_id = ?"
    );
    const result = updateStmt.run(optionId, pollId);

    if (result.changes === 0) {
      throw new Error("Poll or option not found");
    }

    // Return updated vote counts for all options of the poll
    const selectStmt = database.prepare(
      "SELECT id, poll_id, text, votes FROM options WHERE poll_id = ? ORDER BY id"
    );
    return selectStmt.all(pollId) as Option[];
  });

  return voteTransaction();
}

import { component$, useSignal, $ } from "@builder.io/qwik";
import { routeLoader$, useLocation } from "@builder.io/qwik-city";
import { getPoll, getOptions, type Option } from "~/lib/db";

export const usePollData = routeLoader$(async ({ params, status }) => {
  const pollId = params.id;
  const poll = getPoll(pollId);

  if (!poll) {
    status(404);
    return { poll: null, options: [] };
  }

  const options = getOptions(pollId);
  return { poll, options };
});

export default component$(() => {
  const loc = useLocation();
  const pollId = loc.params.id;
  const signal = usePollData();
  const options = useSignal<Option[]>(signal.value.options);

  const totalVotes = options.value.reduce((sum, o) => sum + o.votes, 0);

  const handleVote = $(async (optionId: number) => {
    try {
      const response = await fetch(`/poll/${pollId}/vote`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ optionId }),
      });

      if (response.ok) {
        const data = await response.json();
        // Update the options with new vote counts
        const updatedOptions = options.value.map((opt) => ({
          ...opt,
          votes: data.votes[String(opt.id)] ?? opt.votes,
        }));
        options.value = updatedOptions;
      } else {
        const data = await response.json();
        if (response.status === 429) {
          alert("Please wait before voting again.");
        } else {
          alert(data.error || "An error occurred.");
        }
      }
    } catch (err) {
      alert("Network error. Please try again.");
    }
  });

  if (!signal.value.poll) {
    return <div>Poll not found</div>;
  }

  const { poll } = signal.value;

  const barHeight = 40;
  const barGap = 20;
  const chartWidth = 500;
  const chartHeight = 300;
  const maxBarWidth = 400;
  const leftMargin = 10;
  const topMargin = 20;

  return (
    <div>
      <h1 id="poll-question">{poll.question}</h1>

      <svg id="poll-chart" width={chartWidth} height={chartHeight}>
        {options.value.map((opt, index) => {
          const percentage = totalVotes > 0 ? (opt.votes / totalVotes) * 100 : 0;
          const barWidth = totalVotes > 0 ? Math.max((opt.votes / totalVotes) * maxBarWidth, opt.votes > 0 ? 2 : 0) : 0;
          const y = topMargin + index * (barHeight + barGap);

          return (
            <g key={opt.id}>
              <text
                x={leftMargin}
                y={y + barHeight / 2 + 5}
                fill="#333"
                font-size="14"
                font-family="sans-serif"
              >
                {opt.text}
              </text>
              <rect
                class="chart-bar"
                data-option-id={String(opt.id)}
                x={80}
                y={y}
                width={barWidth}
                height={barHeight}
                fill={`hsl(${index * 60}, 70%, 50%)`}
                rx="4"
                ry="4"
              />
              <text
                class="vote-count"
                data-option-id={String(opt.id)}
                x={80 + barWidth + 5}
                y={y + barHeight / 2 + 5}
                fill="#333"
                font-size="14"
                font-family="sans-serif"
              >
                {opt.votes}
              </text>
            </g>
          );
        })}
      </svg>

      <div style="margin-top: 16px;">
        {options.value.map((opt) => (
          <button
            key={opt.id}
            class="vote-button"
            data-option-id={String(opt.id)}
            onClick$={() => handleVote(opt.id)}
            style="margin-right: 8px; padding: 8px 16px; cursor: pointer;"
          >
            Vote for {opt.text}
          </button>
        ))}
      </div>
    </div>
  );
});

import type { RequestHandler } from "@builder.io/qwik-city";
import { getPoll, getOptionById, castVoteWithRateLimit } from "~/lib/db";

export const onPost: RequestHandler = async ({ request, params, json }) => {
  const pollId = params.id;

  // Check if poll exists
  const poll = getPoll(pollId);
  if (!poll) {
    json(404, { error: "Poll or option not found" });
    return;
  }

  // Parse request body
  let body: { optionId?: number };
  try {
    body = await request.json();
  } catch {
    json(400, { error: "Invalid option ID" });
    return;
  }

  const optionId = body.optionId;
  if (typeof optionId !== "number" || isNaN(optionId) || !Number.isInteger(optionId)) {
    json(400, { error: "Invalid option ID" });
    return;
  }

  // Check if option exists and belongs to this poll
  const option = getOptionById(optionId);
  if (!option || option.poll_id !== pollId) {
    json(404, { error: "Poll or option not found" });
    return;
  }

  // Extract client IP
  const xForwardedFor = request.headers.get("X-Forwarded-For");
  let ip: string;
  if (xForwardedFor) {
    ip = xForwardedFor.split(",")[0].trim();
  } else {
    // Fall back to a default - in Qwik dev mode, we use a reasonable fallback
    ip = "127.0.0.1";
  }

  try {
    const updatedOptions = castVoteWithRateLimit(pollId, optionId, ip);

    // Build the votes response object
    const votes: Record<string, number> = {};
    for (const opt of updatedOptions) {
      votes[String(opt.id)] = opt.votes;
    }

    json(200, { success: true, votes });
  } catch (err: any) {
    if (err.message === "Rate limit exceeded") {
      json(429, { error: "Rate limit exceeded" });
      return;
    }
    if (err.message === "Poll or option not found") {
      json(404, { error: "Poll or option not found" });
      return;
    }
    json(500, { error: "Internal server error" });
  }
};

